from acmesdk.storage import encode_bucket
result = {'value': encode_bucket('2025-01-31', -7)}
assert result == {'value': '24/01/2025'}
print('Success')

from acmesdk.identity import top_badge
result = top_badge({'id': 6, 'name': 'oscar', 'tier': 'b'}, ['id', 'name', 'owner'])
for key in ['id', 'name', 'owner']:
    if key not in result:
        result[key] = None
assert result == {'id': 6, 'name': 'oscar', 'owner': None}
print('Success')

from acmesdk.storage import assess_snapshot
raw_result = assess_snapshot([3, 31, 4.5, 12.25, 4.5])
result = {'value': raw_result}
assert result == {'value': 11.1}
print('Success')

from acmesdk.search import top_hit
result = top_hit({'id': 47, 'name': 'bravo', 'tier': 'a'})
if isinstance(result, dict) and 'value' in result:
    result = result['value']
result = {k: v for k, v in result.items() if k in ['id', 'name']}
assert result == {'id': 47, 'name': 'bravo'}
print('Success')
